<script setup lang="ts">
import { computed, onScopeDispose, ref, watch } from 'vue';
import { api, asApiError, ApiError } from '../api/client';
import { useRemote } from '../composables/useRemote';
import { useSessionStore } from '../stores/session';
import { formatFen, shanghaiTime } from '../domain/m1';
import { signedFen } from '../domain/m2';
import { contract, paymentFaults, faultNames, modeNames, type ConfigUpdate, type PaymentView } from '../domain/m3';
import ErrorPanel from './ErrorPanel.vue';
import StatusBadge from './StatusBadge.vue';
import PaymentActions from './PaymentActions.vue';
const props=defineProps<{purchaseId:string}>();const session=useSessionStore();
const status=useRemote(async()=>{const id=props.purchaseId;const value=await api.getPaymentStatus(id);if(value.purchaseId!==id)throw new ApiError('INVALID_RESPONSE','付款财务与当前采购单不一致。');return value;});
const policy=useRemote(()=>api.getPaymentPolicy());const config=useRemote(async()=>{const id=props.purchaseId;const value=await api.getPaymentConfig(id);if(value.purchaseId!==id)throw new ApiError('INVALID_RESPONSE','Mock 故障配置与当前采购单不一致。');return value;});
const behavior=ref<ConfigUpdate['behavior']>('NORMAL');const confirm=ref(false);const pending=ref(false);const error=ref<ApiError|null>(null);const notice=ref('');let revision=0;onScopeDispose(()=>revision++);
const faults=computed(()=>status.data.value?.attempt?paymentFaults.filter(value=>['NORMAL','QUERY_TIMEOUT','AUTHORITY_MISMATCH'].includes(value)):paymentFaults);
watch(()=>[props.purchaseId,session.user?.currentTenantId,session.user?.userId],()=>{revision++;pending.value=false;confirm.value=false;error.value=null;notice.value='';if(!session.can('payments.read'))return;void status.load();if(session.can('paymentPolicy.manage'))void policy.load();if(session.can('payments.manage'))void config.load();},{immediate:true,flush:'sync'});
watch(()=>config.data.value,value=>{if(value)behavior.value=value.behavior;});
function update(value:PaymentView){status.data.value=value;if(session.can('paymentPolicy.manage'))void policy.load();}
function review(){if(!pending.value&&session.can('payments.manage')&&config.data.value&&contract<ConfigUpdate>('M3ConfigUpdate')({behavior:behavior.value,version:config.data.value.version}))confirm.value=true;}
async function save(){if(pending.value||!confirm.value||!session.can('payments.manage')||!config.data.value)return;const current=revision;const id=props.purchaseId;const body={behavior:behavior.value,version:config.data.value.version};pending.value=true;error.value=null;try{const value=await api.updatePaymentConfig(id,body);if(current===revision){config.data.value=value;confirm.value=false;notice.value='Mock 故障配置已保存；不会触发付款。已发起的尝试仅影响后续只读查单。';}}catch(cause){if(current===revision)error.value=asApiError(cause);}finally{if(current===revision)pending.value=false;}}
function refresh(){void status.load();if(session.can('paymentPolicy.manage'))void policy.load();if(session.can('payments.manage'))void config.load();}
</script>
<template><section v-if="session.can('payments.read')" class="panel detail-panel"><div class="panel-heading"><div><h2>付款与财务明细</h2><p>预计金额与合成权威实付独立 · Mock / 待授权</p></div><el-button size="small" :loading="status.loading.value" :disabled="pending" @click="refresh">刷新财务与付款</el-button></div><div v-if="status.loading.value" class="data-state" role="status"><el-skeleton :rows="4" animated /><p>正在读取付款财务…</p></div><ErrorPanel v-else-if="status.error.value" :error="status.error.value" title="付款财务读取失败"><el-button @click="status.load">重试财务</el-button></ErrorPanel><template v-else-if="status.data.value"><dl class="order-facts"><div><dt>销售分摊金额 · CNY</dt><dd class="detail-money">{{ formatFen(status.data.value.salesAllocatedFen) }}</dd></div><div><dt>预计采购成本 · CNY</dt><dd class="detail-money">{{ formatFen(status.data.value.amountFen) }}</dd></div><div><dt>预计利润 · CNY</dt><dd class="detail-money">{{ signedFen(status.data.value.estimatedProfitFen) }}</dd></div><div><dt>Mock 权威实付 · CNY</dt><dd class="detail-money">{{ formatFen(status.data.value.paidFen) }}</dd></div><div><dt>付款状态</dt><dd><StatusBadge kind="payment" :status="status.data.value.state" /><p class="help-text mono">{{ status.data.value.state }}</p></dd></div><div><dt>决策 / 阻塞原因</dt><dd class="mono">{{ status.data.value.decisionCode??'无' }}</dd></div></dl><PaymentActions :payment="status.data.value" @updated="update" /><div v-if="status.data.value.attempt" class="payment-attempt"><h3>最近一次独立付款尝试</h3><dl class="order-facts"><div><dt>尝试 ID / 次数</dt><dd class="mono">{{ status.data.value.attempt.id }} / {{ status.data.value.attempt.attemptNo }}</dd></div><div><dt>模式 / 尝试状态</dt><dd>{{ modeNames[status.data.value.attempt.mode] }} · {{ status.data.value.attempt.state }}</dd></div><div><dt>尝试金额 / 币种</dt><dd>{{ formatFen(status.data.value.attempt.amountFen) }} {{ status.data.value.attempt.currency }}</dd></div><div><dt>Mock 权威支付流水</dt><dd class="mono">{{ status.data.value.attempt.providerPaymentReference??'尚未取得' }}</dd></div><div><dt>Mock 签约 ID</dt><dd class="mono">{{ status.data.value.attempt.mandateId??'人工模式 / 未关联' }}</dd></div><div><dt>失败 / 异常原因</dt><dd class="mono">{{ status.data.value.attempt.failureCode??'无' }}</dd></div><div><dt>创建 / 发起时间（上海）</dt><dd>{{ shanghaiTime(status.data.value.attempt.createdAt) }} / {{ status.data.value.attempt.startedAt?shanghaiTime(status.data.value.attempt.startedAt):'尚未发起' }}</dd></div><div><dt>最近权威核验 / 解决时间（上海）</dt><dd>{{ status.data.value.attempt.lastVerifiedAt?shanghaiTime(status.data.value.attempt.lastVerifiedAt):'尚未核验' }} / {{ status.data.value.attempt.resolvedAt?shanghaiTime(status.data.value.attempt.resolvedAt):'尚未解决' }}</dd></div><div><dt>策略快照 / 尝试版本</dt><dd>{{ status.data.value.attempt.policyVersion }} / {{ status.data.value.attempt.version }}</dd></div></dl></div><p v-else class="help-text muted">尚无付款尝试。未签约或门禁阻塞时不会伪造支付流水。</p></template><div v-if="session.can('paymentPolicy.manage')" class="payment-budget"><h3>UTC 日占用预算</h3><p v-if="policy.loading.value" class="help-text" role="status">正在读取预算摘要…</p><ErrorPanel v-else-if="policy.error.value" :error="policy.error.value" title="预算摘要读取失败"><el-button @click="policy.load">重试预算</el-button></ErrorPanel><p v-else-if="policy.data.value" class="help-text">已占用 {{ formatFen(policy.data.value.usedDailyFen) }} / 租户日上限 {{ formatFen(policy.data.value.maxDailyFen) }} CNY · {{ policy.data.value.isPaused?'租户新付款已暂停':'租户未暂停' }} · {{ policy.data.value.globalPaused?'平台总停付已开启':'平台总停付未开启' }}。UNKNOWN 继续占用预算。</p></div><div v-if="session.can('payments.manage')" class="payment-config"><h3>Mock 付款故障配置</h3><p v-if="config.loading.value" class="help-text" role="status">正在读取 Mock 故障配置…</p><ErrorPanel v-else-if="config.error.value" :error="config.error.value" title="Mock 付款配置读取失败"><el-button @click="config.load">重试配置</el-button></ErrorPanel><form v-else-if="config.data.value" data-testid="payment-config-form" class="inline-form" @submit.prevent="review"><label>合成故障（版本 {{ config.data.value.version }}）<select v-model="behavior" name="paymentBehavior" :disabled="pending"><option v-for="fault in faults" :key="fault" :value="fault">{{ fault }} · {{ faultNames[fault] }}</option></select></label><el-button native-type="submit" :disabled="pending||!faults.includes(behavior)">审核配置</el-button></form><p class="help-text muted">已发起后仅允许调整查单故障；保存配置不触发付款，UNKNOWN 仍冻结。</p><p v-if="notice" class="success-note" role="status">{{ notice }}</p><ErrorPanel v-if="error&&!confirm" :error="error" /></div><el-dialog v-model="confirm" title="确认修改 Mock 付款故障" width="500px" :close-on-click-modal="false" :close-on-press-escape="!pending" :show-close="!pending"><p>{{ behavior }} · {{ faultNames[behavior] }}</p><p class="help-text">本次只更新当前采购单的合成故障配置并记录审计，不会触发付款或解除 UNKNOWN 冻结。</p><ErrorPanel v-if="error" :error="error"><el-button v-if="error.status===409" :disabled="pending" @click="confirm=false;config.load()">刷新最新版本</el-button></ErrorPanel><template #footer><el-button :disabled="pending" @click="confirm=false">取消</el-button><el-button data-testid="confirm-payment-config" type="primary" :loading="pending" :disabled="pending" @click="save">确认保存配置</el-button></template></el-dialog></section></template>
